/**
 * Conversation engine: turns one caller utterance into one spoken reply.
 *
 * Business-agnostic. It knows about:
 *   - the business it was given (profile, hours, FAQs, languages),
 *   - the call language,
 *   - a few core tools (set_language, request_human, end_call),
 *   - the workflow sessions enabled for this business (e.g. restaurant ordering).
 *
 * The model reads what the caller said and calls tools. Every tool runs as
 * deterministic code. Fixed lines (readbacks, "order placed", handoffs) are
 * generated by code in the call language, never improvised by the model.
 *
 * Telephony-free on purpose: the phone server, the text simulator and the
 * tests all drive this same class.
 */
import { LANGUAGES, phrases } from './languages.js';
import { openStatus, nextOpening } from './menu-service.js';
import { formatPhone, speakPhone, normalizePhone } from './order-state.js';

const MAX_TOOL_ROUNDS = 5;
const MAX_HISTORY_MESSAGES = 40;
const ALLERGY_PATTERN = /(?<![\p{L}\p{M}])(allerg\w*|anaphyla\w*|celiac|coeliac|epipen|peanuts?|tree nuts?|nuts?|gluten|dairy|lactose|shellfish|sesame|alergia|alérgico|alérgica|allergie|एलर्जी|అలర్జీ)(?![\p{L}\p{M}])/iu;

export class ConversationEngine {
    /**
     * @param {object} o
     * @param {object} o.llm        OpenAI-compatible client (chat.completions.create)
     * @param {string} o.model
     * @param {object} o.business   one business from BusinessRegistry (never more)
     * @param {object} o.location   the location this call was routed to
     * @param {object[]} o.workflows workflow sessions for this call
     * @param {object} o.submitter  this business's submitter (used for callback requests)
     * @param {string} o.instructions core prompt text
     */
    constructor({
        llm, model, business, location, workflows, submitter, instructions,
        callId, callerPhone = null, routedBy = null, allowOrdersWhenClosed = false,
        clock = () => new Date(), temperature = 0.3, llmTimeoutMs = 10000, logger = console,
    }) {
        Object.assign(this, { llm, model, business, location, workflows, submitter, clock, temperature, llmTimeoutMs, allowOrdersWhenClosed, callId, routedBy });
        this.log = logger;
        this.callerPhone = normalizePhone(callerPhone);
        this.instructions = instructions
            .replaceAll('{{AGENT_NAME}}', business.agentName)
            .replaceAll('{{BUSINESS_NAME}}', business.name);
        this.language = business.languages.default;
        this.languageHistory = [{ language: this.language, at: clock().toISOString(), reason: 'business_default' }];
        this.messages = [];
        this.turn = 0;
        this.lastUserUtterance = '';
        this.consecutiveFailures = 0;
        this.events = [];
        this.handoff = null;
        this.ended = false;
        this.tools = this.buildTools();
    }

    get phrases() { return phrases(this.language); }

    event(type, data = {}) {
        const e = { type, at: this.clock().toISOString(), language: this.language, ...data };
        this.events.push(e);
        return e;
    }

    buildTools() {
        const core = [];
        if (this.business.languages.enabled.length > 1) {
            core.push({
                name: 'set_language',
                description: 'Switch the call language when the caller asks or is clearly speaking another enabled language.',
                parameters: { type: 'object', properties: { language: { type: 'string', enum: this.business.languages.enabled } }, required: ['language'] },
            });
        }
        core.push(
            {
                name: 'request_human',
                description: 'Get staff involved: the caller asked for a person, complained, or you cannot help safely.',
                parameters: { type: 'object', properties: { reason: { type: 'string' } }, required: ['reason'] },
            },
            {
                name: 'end_call',
                description: 'End the call after a goodbye when the caller is finished and nothing is in progress.',
                parameters: { type: 'object', properties: {} },
            },
        );
        return [...core.map(fn => ({ type: 'function', function: fn })), ...this.workflows.flatMap(w => w.tools)];
    }

    greeting() {
        const lang = this.language;
        const p = this.phrases;
        let text = this.business.languages.greetings[lang] || p.greeting(this.business.shortName, this.business.agentName);
        const others = this.business.languages.enabled.filter(c => c !== lang);
        if (others.length && !this.business.languages.greetings[lang]) {
            text += ' ' + p.languageOffer(others.map(c => (lang === 'en' ? LANGUAGES[c].name : LANGUAGES[c].native)).join(', '));
        }
        this.messages.push({ role: 'assistant', content: text });
        this.event('greeting');
        return text;
    }

    hours() {
        return openStatus(this.location.hours, this.clock(), this.business.timezone);
    }

    /** true / false, or null when hours can't be determined (never guessed). */
    isOpen() {
        if (this.allowOrdersWhenClosed) return true;
        const h = this.hours();
        return h.known ? h.open : null;
    }

    nextOpeningText() {
        const at = nextOpening(this.location.hours, this.clock(), this.business.timezone, 7);
        if (!at) return '';
        return ` Next opening: ${new Intl.DateTimeFormat('en-US', { timeZone: this.business.timezone, weekday: 'long', hour: 'numeric', minute: '2-digit' }).format(at)}.`;
    }

    systemPrompt(utterance, detectedLanguage) {
        const h = this.hours();
        const openLine = !h.known
            ? `Open status: unknown (today's hours: ${h.today_hours || 'not configured'}). Do not guess.`
            : `Currently ${h.open ? 'OPEN' : 'CLOSED'}. Today's hours: ${h.today_hours}.${h.open ? '' : this.nextOpeningText()}`;
        const weekHours = Object.entries(this.location.hours || {}).map(([d, v]) => `${d}: ${v}`).join('; ');
        const enabled = this.business.languages.enabled.map(c => `${LANGUAGES[c].name} (${c})`).join(', ');

        const parts = [
            this.instructions,
            '',
            'BUSINESS',
            `${this.business.name}${this.location.name ? ` — ${this.location.name}` : ''}. Address: ${this.location.address || 'not configured'}. Phone: ${this.location.phone || 'not configured'}.`,
            `Local time: ${h.local_time}. ${openLine}`,
            `Weekly hours: ${weekHours || 'not configured'}.`,
            `Caller ID: ${this.callerPhone ? formatPhone(this.callerPhone) : 'not available'}.`,
        ];
        if (this.business.faqs.length) {
            parts.push('FAQs (verified answers):', ...this.business.faqs.map(f => `- Q: ${f.q} A: ${f.a}`));
        }
        parts.push(
            '',
            `CALL LANGUAGE: ${LANGUAGES[this.language].name} (${this.language}). Enabled languages: ${enabled}.`,
        );
        if (detectedLanguage && detectedLanguage !== this.language) {
            const known = this.business.languages.enabled.includes(detectedLanguage);
            parts.push(`Speech recognition heard mostly ${LANGUAGES[detectedLanguage]?.name || detectedLanguage} in the last utterance${known ? '' : ' (not enabled for this business)'}.`);
        }
        for (const w of this.workflows) parts.push('', w.promptSection());
        if (ALLERGY_PATTERN.test(utterance)) {
            parts.push('', 'NOTE: The caller just mentioned an allergy or dietary restriction. You cannot confirm any item is safe. Record it, and offer a staff callback if they need ingredient confirmation.');
        }
        return parts.join('\n');
    }

    trimHistory() {
        if (this.messages.length <= MAX_HISTORY_MESSAGES) return;
        let cut = this.messages.length - MAX_HISTORY_MESSAGES;
        while (cut < this.messages.length && this.messages[cut].role !== 'user') cut++;
        this.messages = this.messages.slice(cut);
    }

    async callModel(utterance, detectedLanguage) {
        const started = Date.now();
        const completion = await this.llm.chat.completions.create({
            model: this.model,
            temperature: this.temperature,
            max_tokens: 300,
            tools: this.tools,
            tool_choice: 'auto',
            messages: [{ role: 'system', content: this.systemPrompt(utterance, detectedLanguage) }, ...this.messages],
        }, { timeout: this.llmTimeoutMs, maxRetries: 0 });
        const message = completion?.choices?.[0]?.message;
        if (!message || (message.content == null && !Array.isArray(message.tool_calls))) throw new Error('malformed_model_response');
        this.event('model_response', { ms: Date.now() - started, tool_calls: (message.tool_calls || []).map(t => t.function?.name) });
        return message;
    }

    isFinished() {
        return this.ended || Boolean(this.handoff) || this.workflows.some(w => w.isComplete());
    }

    /**
     * Handle one caller utterance.
     * @param {string} utterance
     * @param {{ detectedLanguage?: string }} [meta]
     * @returns {Promise<{say: string, endCall: boolean, handoff: boolean, language: string}>}
     */
    async handleUtterance(utterance, { detectedLanguage = null } = {}) {
        const text = String(utterance || '').trim();
        this.turn += 1;
        this.lastUserUtterance = text;
        this.event('caller_said', { chars: text.length, detected_language: detectedLanguage });

        if (this.isFinished()) return this.reply(this.phrases.alreadyDone, true);

        this.messages.push({ role: 'user', content: text });
        this.trimHistory();

        let outcome = null;
        try {
            for (let round = 0; round < MAX_TOOL_ROUNDS; round++) {
                const message = await this.callModel(text, detectedLanguage);
                const toolCalls = message.tool_calls || [];

                if (toolCalls.length === 0) {
                    const say = (message.content || '').trim() || this.phrases.sayOnceMore;
                    this.messages.push({ role: 'assistant', content: say });
                    this.consecutiveFailures = 0;
                    return this.reply(say, false);
                }

                this.messages.push({ role: 'assistant', content: message.content || null, tool_calls: toolCalls });
                for (const call of toolCalls) {
                    const result = await this.runTool(call);
                    this.messages.push({ role: 'tool', tool_call_id: call.id, content: JSON.stringify(result.forModel) });
                    if (result.outcome && !outcome) outcome = result.outcome;
                }
                if (outcome) break;
            }
        } catch (error) {
            this.consecutiveFailures += 1;
            this.event('model_error', { error: error.message, consecutive: this.consecutiveFailures });
            this.log.error('❌ Model call failed:', error.message);
            this.dropDanglingToolCalls();
            if (this.consecutiveFailures >= 2) outcome = await this.failToCallback('model_unavailable');
            else return this.reply(this.phrases.sayAgain, false);
        }

        if (outcome?.failToCallback) outcome = await this.failToCallback(outcome.failToCallback);
        if (!outcome) {
            this.dropDanglingToolCalls();
            outcome = { say: this.phrases.sayOnceMore, endCall: false, handoff: false };
        } else {
            this.consecutiveFailures = 0;
        }
        this.messages.push({ role: 'assistant', content: outcome.say });
        return { ...outcome, language: this.language };
    }

    reply(say, endCall) {
        return { say, endCall, handoff: false, language: this.language };
    }

    dropDanglingToolCalls() {
        while (this.messages.length) {
            const last = this.messages[this.messages.length - 1];
            if (last.role === 'tool' || (last.role === 'assistant' && last.tool_calls)) this.messages.pop();
            else break;
        }
    }

    async runTool(call) {
        const name = call.function?.name;
        let args;
        try {
            args = call.function?.arguments ? JSON.parse(call.function.arguments) : {};
            if (typeof args !== 'object' || args === null || Array.isArray(args)) throw new Error('not an object');
        } catch {
            this.event('tool', { name, ok: false, error: 'malformed_arguments' });
            return { forModel: { ok: false, error: 'malformed_arguments' } };
        }

        let result = await this.runCoreTool(name, args);
        if (!result) {
            const ctx = {
                turn: this.turn,
                lastUserUtterance: this.lastUserUtterance,
                language: this.language,
                phrases: this.phrases,
                isOpen: this.isOpen(),
                businessName: this.business.shortName,
                event: (type, data) => this.event(type, data),
            };
            for (const w of this.workflows) {
                result = await w.runTool(name, args, ctx);
                if (result) break;
            }
        }
        if (!result) result = { forModel: { ok: false, error: 'unknown_tool' } };
        this.event('tool', { name, ok: Boolean(result.forModel?.ok), error: result.forModel?.ok ? undefined : result.forModel?.error });
        return result;
    }

    async runCoreTool(name, args) {
        switch (name) {
            case 'set_language': {
                const code = args.language;
                if (!this.business.languages.enabled.includes(code)) {
                    return { forModel: { ok: false, error: 'language_not_enabled', enabled: this.business.languages.enabled } };
                }
                if (code !== this.language) {
                    this.language = code;
                    this.languageHistory.push({ language: code, at: this.clock().toISOString(), reason: 'caller' });
                    this.event('language_changed', { to: code });
                }
                return { forModel: { ok: true, language: code, note: `Reply in ${LANGUAGES[code].name} from now on.` } };
            }
            case 'request_human':
                this.event('handoff_requested', { reason: args.reason });
                return { forModel: { ok: true, note: 'Handled by system.' }, outcome: await this.requestHuman(args.reason) };
            case 'end_call':
                if (this.workflows.some(w => w.hasUnfinishedWork())) {
                    return { forModel: { ok: false, error: 'work_in_progress', message: 'Something is still unfinished (for example an unsubmitted order). Ask the caller if they want to finish it.' } };
                }
                this.ended = true;
                for (const w of this.workflows) w.onEnd?.();
                return { forModel: { ok: true }, outcome: { say: this.phrases.goodbye(this.business.shortName), endCall: true, handoff: false } };
            default:
                return null;
        }
    }

    contactPhone() {
        for (const w of this.workflows) if (w.contactPhone()) return w.contactPhone();
        return this.callerPhone;
    }

    async requestHuman(reason) {
        if (!this.contactPhone()) {
            // Can't promise a callback without a number; keep the call going.
            return { say: this.phrases.askCallbackNumber, endCall: false, handoff: false };
        }
        return this.failToCallback(reason || 'caller_requested_human');
    }

    /**
     * Human path: a callback request sent to this business's staff.
     * (Live call transfer comes with the telephony milestone.)
     */
    async failToCallback(reason) {
        const phone = this.contactPhone();
        for (const w of this.workflows) w.onHandoff(reason);
        let sent = false;
        if (phone && this.business.escalation.callbackEnabled && this.submitter?.notifyCallback) {
            const r = await this.submitter.notifyCallback({
                call_id: this.callId,
                phone,
                name: this.workflows.map(w => w.contactName?.()).find(Boolean) || null,
                reason,
                language: this.language,
                order: this.workflows[0]?.snapshot() || null,
                locationId: this.location.id,
            });
            sent = Boolean(r?.success);
        }
        this.handoff = { reason, callback_sent: sent };
        this.event('handoff', { reason, callback_sent: sent });
        const say = sent
            ? this.phrases.callbackSent(speakPhone(phone))
            : this.phrases.cannotFinish(this.business.shortName, this.location.phone);
        return { say, endCall: true, handoff: true };
    }

    /** Structured, language-neutral record of the call. */
    callState() {
        return {
            call_id: this.callId,
            business_id: this.business.id,
            location_id: this.location.id,
            routed_by: this.routedBy,
            language: this.language,
            language_history: this.languageHistory,
            handoff: this.handoff,
            workflows: Object.fromEntries(this.workflows.map(w => [w.id, w.snapshot()])),
        };
    }
}
